// REFACTOR по SRP: тонкий сервис + узкие сотрудники
class OrderService {                              // только бизнес-правила
  constructor(
    private readonly orders: OrderRepository,     // доступ к данным (порт)
    private readonly gateway: PaymentGateway,     // платёжный шлюз (порт)
    private readonly events: EventBus,            // публикация событий (порт)
  ) {}

  async create(cmd: CreateOrderCommand): Promise<Order> {
    const order = Order.create(cmd);              // инварианты домена — здесь
    await this.orders.save(order);
    await this.events.publish(new OrderCreated(order.id, order.total));
    return order;
  }
}
