// SO O: реестр реализаций; новый метод = новый файл, старый не трогаем
interface PaymentMethod {
  readonly kind: PaymentKind;
  charge(amountCents: number, ctx: ChargeCtx): Promise<ChargeResult>;
}

const methods: Record<PaymentKind, PaymentMethod> = {
  card: new CardMethod(),
  sbp: new SbpMethod(),
  invoice: new InvoiceMethod(),
  // 'crypto': new CryptoMethod(),   // <- расширение = добавление записи/файла
};

export async function charge(kind: PaymentKind, amount: number, ctx: ChargeCtx) {
  const method = methods[kind] ?? never(kind);   // exhaustive-проверка типа
  return method.charge(amount, ctx);
}

// Классический пример нарушения (Rectangle/Square) в терминах TS
interface Shape { area(): number; setWidth(w: number): void; setHeight(h: number): void; }

class Rectangle implements Shape {
  constructor(public w: number, public h: number) {}
  area() { return this.w * this.h; }
  setWidth(w: number) { this.w = w; }
  setHeight(h: number) { this.h = h; }
}

class Square implements Shape {              // «у квадрата ширина = высота»
  constructor(private side: number) {}
  area() { return this.side ** 2; }
  setWidth(w: number) { this.side = w; }     // меняет и высоту -> инварианты вызывающего ломаются
  setHeight(h: number) { this.side = h; }
}

function totalArea(shapes: Shape[]) { return shapes.reduce((s, x) => s + x.area(), 0); }
// setWidth/s setHeight на Square меняет «то, что не просили» -> нарушение L.

