// Порт (абстракция) — живёт рядом с доменом
export interface PaymentGateway {
  charge(input: ChargeInput, signal?: AbortSignal): Promise<ChargeReceipt>;
}

// Домен зависит только от порта — ни Stripe, ни HTTP, ни таймеров
export class BillingService {
  constructor(private readonly gateway: PaymentGateway) {}
  async bill(order: Order) {
    const receipt = await withTimeout(this.gateway.charge({ amount: order.total }), 5_000);
    order.markPaid(receipt.id);
  }
}

