// Builder: пошаговая сборка с инвариантами на finish()
class OrderDraftBuilder {
  private items: Array<{ sku: string; qty: number; priceCents: number }> = [];
  private customerId?: string;
  private coupon?: string;

  withCustomer(id: string) { this.customerId = id; return this; }
  addItem(sku: string, qty: number, priceCents: number) {
    this.items.push({ sku, qty, priceCents }); return this;
  }
  withCoupon(code: string) { this.coupon = code; return this; }

  build(): Order {                      // валидация — в одном месте, «недостроенный» объект невозможен
    if (!this.customerId) throw new Error('customer is required');
    if (this.items.length === 0) throw new Error('items are required');
    return Order.create({ customerId: this.customerId, items: this.items, coupon: this.coupon });
  }
}
const order = new OrderDraftBuilder().withCustomer(u.id).addItem('SKU-1', 2, 49900).build();

// Factory: выбор реализации по данным конфигурации, а не switch в бизнесе
export function createGateway(cfg: GatewayConfig): PaymentGateway {
  switch (cfg.provider) {
    case 'stripe': return new StripeGateway(cfg.stripe);
    case 'sber':   return new SberGateway(cfg.sber);
    default:       return assertNever(cfg.provider);
  }
}

// Adapter: сторонний SDK отвечает своими типами — мы переводим в доменные
interface PaymentProvider { charge(amount: number, currency: string): Promise<{ id: string; status: string }>; }

export class StripeProviderAdapter implements PaymentGateway {      // наш порт
  constructor(private readonly stripe: Stripe) {}
  async charge(input: ChargeInput): Promise<ChargeReceipt> {
    const res = await this.stripe.charges.create({               // чужие имена/типы/ошибки
      amount: input.amount, currency: input.currency, idempotency_key: input.idempotencyKey,
    });
    if (res.status === 'failed') throw new GatewayDeclined(res.failure_message ?? 'declined');
    return { id: res.id, amount: res.amount, status: res.status }; // перевод в наш язык
  }
}

// Decorator/Proxy: кеширующая обёртка репозитория без изменения интерфейса
export class CachedUserRepository implements UserRepository {
  constructor(private readonly base: UserRepository, private readonly redis: Redis) {}
  async findById(id: string): Promise<User | null> {
    const hit = await this.redis.get(`user:${id}`);
    if (hit) return User.fromJSON(JSON.parse(hit));
    const user = await this.base.findById(id);
    if (user) await this.redis.set(`user:${id}`, JSON.stringify(user), 'EX', 300 + Math.random() * 60);
    return user;
  }
  // write-методы прокидываем в базу + инвалидация ключа
}

// Strategy: алгоритм ценообразования за общим интерфейсом
export interface PricingStrategy { price(items: CartItem[], ctx: Ctx): PriceBreakdown; }

export class RegularPricing implements PricingStrategy { /* без скидок */ }
export class VipPricing implements PricingStrategy { /* -10% для VIP */ }
export class CouponPricing implements PricingStrategy { /* по купону из ctx */ }

export function quote(strategy: PricingStrategy, items: CartItem[], ctx: Ctx): PriceBreakdown {
  return strategy.price(items, ctx);          // клиент не знает, какой алгоритм внутри
}

