// State: машина состояний вместо созвезда boolean-флагов
type OrderState =
  | { kind: 'created'; toPaid(): OrderState; toCancelled(reason: string): OrderState }
  | { kind: 'paid';    toShipped(track: string): OrderState; toRefunded(): OrderState }
  | { kind: 'shipped'; toDelivered(): OrderState }
  | { kind: 'cancelled' };
// Недопустимые переходы просто отсутствуют в типе — компилятор ловит ошибки бизнес-логики.

// «До»: god-method — валидация, бизнес, SQL, HTTP-формат и логи в одном
async function handle(data: any, res: any) {
  if (!data?.items) { res.status(400).send('bad'); return; }
  try {
    const rows = await db.query('SELECT ...');            // SQL + бизнес + формат
    const total = rows.reduce((s: number, r: any) => s + r.price * r.qty, 0);
    if (total > 100000) { await db.query('UPDATE vip'); } // скрытое правило
    res.json({ ok: true, total, rows });
  } catch (e) { res.status(500).send('err'); }            // ошибка проглочена без лога/метрики
}

// «После»: слои + доменные имена + явные ошибки
export class CheckoutFacade {                             // Facade + Service Layer
  constructor(private readonly pricing: PricingStrategy, private readonly repo: CartRepository) {}
  async checkout(cmd: CheckoutCommand): Promise<CheckoutReceipt> {
    const cart = await this.repo.find(cmd.cartId);        // Repository
    if (!cart) throw new NotFoundError('cart', cmd.cartId);
    const price = this.pricing.price(cart.items, cmd.ctx); // Strategy
    cart.checkout(price);                                 // доменные правила — в домене
    await this.repo.save(cart);
    return CheckoutReceipt.from(cart, price);             // отдельный DTO на выход
  }
}
